import csv, math

def load_data():
    xs=[]; ys=[]
    with open('/app/spectrum.csv') as f:
        r=csv.DictReader(f)
        for row in r:
            xs.append(float(row['raman_shift_cm-1']))
            ys.append(float(row['intensity']))
    return xs, ys

def model(p, x):
    x0, lg, lA, off = p
    g = math.exp(lg)
    A = math.exp(lA)
    return A*g*g/((x-x0)*(x-x0)+g*g) + off

def sse(p, xs, ys):
    return sum((model(p, x)-y)**2 for x, y in zip(xs, ys))

def solve_linear(A, b):
    n = len(b)
    M = [A[i][:] + [b[i]] for i in range(n)]
    for col in range(n):
        piv = col
        for row in range(col+1, n):
            if abs(M[row][col]) > abs(M[piv][col]):
                piv = row
        if abs(M[piv][col]) < 1e-18:
            return None
        M[col], M[piv] = M[piv], M[col]
        pv = M[col][col]
        for j in range(col, n+1):
            M[col][j] /= pv
        for row in range(n):
            if row == col:
                continue
            fac = M[row][col]
            if abs(fac) > 0.0:
                for j in range(col, n+1):
                    M[row][j] -= fac*M[col][j]
    return [M[i][n] for i in range(n)]

def fit(xs, ys, lo, hi, gamma0):
    X=[]; Y=[]
    for x, y in zip(xs, ys):
        if lo <= x <= hi:
            X.append(x); Y.append(y)
    n = len(X)
    im = max(range(n), key=lambda i: Y[i])
    off0 = sorted(Y)[max(0, n//10)]
    p = [X[im], math.log(gamma0), math.log(max(Y[im]-off0, 1.0)), off0]
    lam = 1e-3
    for it in range(200):
        base = [model(p, x) for x in X]
        r = [base[i]-Y[i] for i in range(n)]
        ss = sum(v*v for v in r)
        J = [[0.0]*4 for _ in range(n)]
        for j in range(4):
            h = 1e-5*(abs(p[j])+1.0)
            pp = p[:]
            pp[j] += h
            for i in range(n):
                J[i][j] = (model(pp, X[i])-base[i])/h
        A = [[0.0]*4 for _ in range(4)]
        g = [0.0]*4
        for i in range(n):
            for a in range(4):
                g[a] += J[i][a]*r[i]
                for b in range(4):
                    A[a][b] += J[i][a]*J[i][b]
        accepted = False
        for attempt in range(30):
            Ad = [row[:] for row in A]
            for i in range(4):
                Ad[i][i] += lam*max(A[i][i], 1e-12)
            delta = solve_linear(Ad, [-v for v in g])
            if delta is None:
                lam *= 10.0
                continue
            pn = [p[i]+delta[i] for i in range(4)]
            ssn = sse(pn, X, Y)
            if ssn < ss:
                p = pn
                lam = max(lam*0.3, 1e-12)
                accepted = True
                break
            lam *= 10.0
        if not accepted:
            break
        if abs(ss-ssn) < 1e-12*(1.0+ss):
            break
    return p, sse(p, X, Y), it+1

xs, ys = load_data()
for name, lo, hi, g0 in [('D', 1250, 1450, 20.0), ('G', 1500, 1700, 20.0), ('2D', 2500, 2850, 30.0)]:
    p, ss, it = fit(xs, ys, lo, hi, g0)
    print(name, 'iter', it, 'SSE', ss)
    print(' x0', p[0])
    print(' gamma', math.exp(p[1]))
    print(' amp', math.exp(p[2]))
    print(' offset', p[3])
